import {courseReportText} from './course-model.js';
import {explorerReportText} from './explorer.js';
import {modeString,PROTECTED} from './core.js';
import {CPU_EXAMPLES,checkJobs,cpuRun,cpuSummary,pageRun,parseReferences,translateAddress,emptyDisk,allocate,fragments,defragment,fragmentedDisk} from './models.js';
import {buildWorkReport,reportDocument,REPORT_CSS} from './reports.js';
import {networkLogText} from './network-ui.js';

const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const fmt=n=>n===null?'—':Number.isInteger(n)?String(n):n.toFixed(2);
const states={new:'Nov',ready:'Spreman',running:'Izvodi se',blocked:'Čeka I/O',done:'Završen'};
const algorithms={fcfs:'FCFS',rr:'Round Robin',sjf:'SJF'};
const colors=['#9180ce','#5e9f9e','#cf9768','#a87da0','#7f9cbd','#ab9a56','#bd7980','#6b9e74'];
const sourceLinks=`<div class="source-links">Za nastavnika: <a href="https://pages.cs.wisc.edu/~remzi/OSTEP/" target="_blank" rel="noopener noreferrer">OSTEP — autori udžbenika</a> · <a href="https://www.gnu.org/software/coreutils/manual/html_node/Mode-Structure.html" target="_blank" rel="noopener noreferrer">GNU — dozvole</a></div>`;

export function createTeaching(ctx){
  const {fs,esc,icon,openApp,toast,ask,download}=ctx;
  let permissionId='welcome',lessonIndex=0,userTab='profiles',address=1024;
  const set=(fn,apps=[])=>{try{fs.transact(fn);ctx.changed();ctx.refresh(...apps);return true;}catch(e){toast(e.message);return false;}};
  const intro=(tag,title,description)=>`<div class="study-heading"><div><span class="label">${tag}</span><h2>${title}</h2><p>${description}</p></div><span class="tag">NASTAVNI MODEL</span></div>`;
  const bindOpen=c=>{for(const b of $$('[data-study-open]',c))b.onclick=()=>openApp(b.dataset.studyOpen);};
  function permissions(id){if(id)permissionId=id;userTab='permissions';openApp('users');ctx.refresh('users');}
  function users(c){
    if(!fs.get(permissionId))permissionId=fs.state.nodes.find(n=>n.type==='file')?.id||'docs';
    c.innerHTML=`<div class="study-app">${intro('PRISTUP I IDENTITET','Tko smije što?','Promijeni simulirani profil i isprobaj kako vlasnik, grupa i ostali određuju pristup.')}<div class="model-callout">${icon('info')}<span>Profili služe vježbi. Prebacivanje je bez lozinke i nije stvarna prijava ni zaštita lokalnog rada.</span></div><div class="study-tabs"><button data-tab="profiles" class="${userTab==='profiles'?'selected':''}">Korisnici</button><button data-tab="permissions" class="${userTab==='permissions'?'selected':''}">Dozvole</button></div><div id="users-content"></div></div>`;
    for(const b of $$('[data-tab]',c))b.onclick=()=>{userTab=b.dataset.tab;users(c);};
    const body=$('#users-content',c);
    if(userTab==='profiles'){
      body.innerHTML=`<div class="profile-grid">${fs.state.users.map(u=>`<article class="profile-card ${u.id===fs.user.id?'current':''}"><span class="profile-avatar">${esc(u.name[0])}</span><h3>${esc(u.name)}</h3><code>${esc(u.id)}</code><p>${u.admin?'Administrator modela':esc(u.groups.join(', '))}</p><button class="button ${u.id===fs.user.id?'secondary':'primary'}" data-user="${esc(u.id)}" ${u.id===fs.user.id?'disabled':''}>${u.id===fs.user.id?'Aktivan profil':'Prebaci profil'}</button></article>`).join('')}</div><div class="model-note">Novi zapisi pripadaju aktivnom profilu. <strong>Nastavnik</strong> u ovom modelu može pristupiti svim zapisima i promijeniti vlasništvo. Korisnici <strong>Učenik</strong> i <strong>Kolega</strong> članovi su grupe <code>razred</code>; Gost nije.</div><details class="study-details"><summary>Dodaj simuliranog korisnika</summary><form id="add-user" class="study-form"><label>Oznaka<input name="username" pattern="[a-z][a-z0-9_]{2,23}" maxlength="24" placeholder="ucenik2" required></label><label>Prikazano ime<input name="displayname" maxlength="50" placeholder="Učenik 2" required></label><label>Grupa<select name="group"><option value="razred">razred</option><option value="gosti">gosti</option></select></label><button class="button primary" ${!fs.user.admin?'disabled':''}>Dodaj profil</button></form><p class="form-hint">Dodavanje je dostupno profilu Nastavnik. Ovdje nemoj unositi lozinke.</p></details>`;
      for(const b of $$('[data-user]',body))b.onclick=()=>ctx.switchUser(b.dataset.user);
      $('#add-user',body).onsubmit=e=>{e.preventDefault();const f=e.currentTarget;try{fs.addUser(f.elements.username.value,f.elements.displayname.value,f.elements.group.value);ctx.changed();users(c);}catch(err){toast(err.message);}};
    }else{
      const n=fs.get(permissionId),canChange=(fs.user.admin||n.owner===fs.user.id)&&(!PROTECTED.includes(n.id)||fs.user.admin);
      body.innerHTML=`<div class="permission-pick"><label>Datoteka ili mapa<select id="permission-target">${fs.state.nodes.map(f=>`<option value="${esc(f.id)}" ${f.id===n.id?'selected':''}>${esc(fs.path(f.id))||'/'}</option>`).join('')}</select></label><button class="button secondary" id="permission-demo">Pripremi primjer 640</button></div><div class="permission-summary"><span>${icon(n.type==='dir'?'files':'file')} ${esc(n.name)}</span><code>${n.mode} · ${modeString(n.mode)}</code></div><p class="study-text">Za pristup se uzima <strong>jedna</strong> skupina dozvola: vlasnik ako je korisnik vlasnik, inače grupa ako joj pripada, inače ostali. Dozvole tih skupina ne zbrajaju se.</p><form id="permission-form"><div class="permission-grid"><div></div><strong>Čitanje · r · 4</strong><strong>Pisanje · w · 2</strong><strong>${n.type==='dir'?'Prolaz':'Izvođenje'} · x · 1</strong>${['Vlasnik','Grupa','Ostali'].map((label,i)=>`<strong>${label}</strong>${[4,2,1].map(bit=>`<label class="permission-bit"><input type="checkbox" data-class="${i}" data-bit="${bit}" aria-label="${label} ${bit===4?'čitanje':bit===2?'pisanje':n.type==='dir'?'prolaz':'izvođenje'}" ${Number(n.mode[i])&bit?'checked':''} ${!canChange?'disabled':''}></label>`).join('')}`).join('')}</div><div class="permission-ownership"><label>Vlasnik<select name="owner" ${!fs.user.admin?'disabled':''}>${fs.state.users.map(u=>`<option ${u.id===n.owner?'selected':''} value="${esc(u.id)}">${esc(u.id)}</option>`).join('')}</select></label><label>Grupa<select name="group" ${!fs.user.admin?'disabled':''}>${['razred','gosti','nastavnici'].map(g=>`<option ${g===n.group?'selected':''}>${g}</option>`).join('')}</select></label><button class="button primary" ${!canChange?'disabled':''}>Primijeni dozvole</button></div></form><p class="form-hint">${n.type==='dir'?'Za otvaranje mape u ovom pregledniku trebaju r i x; za dodavanje, preimenovanje i uklanjanje zapisa trebaju w i x.':'r dopušta čitanje sadržaja, w izmjenu. x označava izvođenje; Orbit ne pokreće kod iz tekstualnih datoteka.'} Za pristup sadržaju potreban je x na svim nadređenim mapama.</p><h3 class="study-subtitle">Učinak na korisnike</h3><div class="table-scroll"><table class="study-table"><thead><tr><th>Profil</th><th>Primjenjuje se</th><th>Čitanje</th><th>Pisanje</th><th>Prolaz / x</th></tr></thead><tbody>${fs.state.users.map(u=>`<tr><td>${esc(u.name)}${u.id===fs.user.id?' · aktivan':''}</td><td>${u.admin?'Admin':u.id===n.owner?'Vlasnik':u.groups.includes(n.group)?'Grupa':'Ostali'}</td>${['r','w','x'].map(flag=>`<td><span class="access-${fs.can(n.id,flag,u.id)?'yes':'no'}">${fs.can(n.id,flag,u.id)?'Da':'Ne'}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="study-actions"><button class="button secondary" id="try-read">Isprobaj čitanje kao ${esc(fs.user.name)}</button><button class="button subtle" data-study-open="terminal">Otvori Terminal</button></div><div id="permission-result" class="model-note" role="status">Promijeni profil u kartici Korisnici i ponovi čitanje.</div>`;
      $('#permission-target',body).onchange=e=>{permissionId=e.target.value;users(c);};
      $('#permission-demo',body).onclick=()=>{if(ctx.dirty()){toast('Prvo preuzmi nespremljeni tekst.');return;}try{if(fs.user.id!=='ucenik')ctx.switchUser('ucenik');let name='dozvole.txt',k=1;while(fs.children('docs').some(x=>x.name===name))name=`dozvole-${k++}.txt`;const file=fs.create('docs',name,'file','Ovaj tekst vlasnik može čitati i mijenjati. Član grupe može ga samo čitati. Ostali nemaju pristup.');fs.chmod(file.id,'640');permissionId=file.id;ctx.changed();users(c);}catch(e){toast(e.message);}};
      $('#permission-form',body).onsubmit=e=>{e.preventDefault();if(ctx.dirty()){toast('Prvo spremi ili preuzmi otvorenu bilješku.');return;}const bits=[0,0,0];for(const ch of $$('input[data-bit]:checked',e.currentTarget))bits[+ch.dataset.class]+=+ch.dataset.bit;try{const owner=e.currentTarget.elements.owner.value,group=e.currentTarget.elements.group.value;if(fs.user.admin&&(n.owner!==owner||n.group!==group))fs.chown(n.id,owner,group);fs.chmod(n.id,bits.join(''));ctx.permissionsChanged();users(c);toast('Dozvole su primijenjene na stvarne radnje u Orbitu.');}catch(err){toast(err.message);}};
      $('#try-read',body).onclick=()=>{const out=$('#permission-result',body);try{const value=n.type==='dir'?fs.list(n.id).map(x=>x.name).join(', '):fs.read(n.id);out.textContent='Pristup dopušten. '+(value||'(prazno)');out.classList.remove('denied');ctx.refresh('lab','journal');}catch(e){out.textContent=e.message;out.classList.add('denied');ctx.refresh('lab','journal');}};
      bindOpen(body);
    }
  }

  function cpu(c){
    const config=fs.state.learning.cpu,s=cpuRun(config,config.steps),summary=cpuSummary(s);
    const comparison=Object.keys(algorithms).map(algorithm=>({algorithm,...cpuSummary(cpuRun({...config,algorithm}))}));
    const segments=[];for(const slot of s.timeline){const prev=segments.at(-1);if(prev?.id===slot.id)prev.end=slot.end;else segments.push({...slot});}
    c.innerHTML=`<div class="study-app">${intro('PROCESOR I RASPOREĐIVANJE','Jedan CPU. Više procesa.','Raspoređivač bira spreman proces. Jedan korak ovdje traje jednu simuliranu vremensku jedinicu.')}<div class="concept-strip"><span><b>Spreman</b> čeka CPU</span><span><b>Izvodi se</b> koristi CPU</span><span><b>Čeka I/O</b> čeka uređaj</span></div><div class="sim-controls"><label>Algoritam<select id="cpu-algorithm"><option value="fcfs" ${config.algorithm==='fcfs'?'selected':''}>FCFS — redoslijedom dolaska</option><option value="rr" ${config.algorithm==='rr'?'selected':''}>Round Robin — kružno</option><option value="sjf" ${config.algorithm==='sjf'?'selected':''}>SJF — najkraći sljedeći CPU odsječak</option></select></label><label>Kvant<input id="cpu-quantum" type="number" min="1" max="10" value="${config.quantum}" ${config.algorithm!=='rr'?'disabled':''}></label><button id="cpu-step" class="button primary" ${summary.done?'disabled':''}>${icon('play')} Korak +1</button><button id="cpu-run" class="button secondary" ${summary.done?'disabled':''}>Do kraja</button><button id="cpu-reset" class="button subtle">Početak</button></div><p class="form-hint">${config.algorithm==='fcfs'?'FCFS ne prekida proces samo zato što je stigao drugi; CPU se oslobađa završetkom ili I/O čekanjem.':config.algorithm==='rr'?'Kvant je najveći broj uzastopnih jedinica CPU-a prije povratka procesa na kraj reda spremnih.':'SJF ovdje bira najkraći poznati sljedeći CPU odsječak i ne prekida već pokrenuti odsječak.'}</p><div class="cpu-stage"><div class="cpu-chip">${icon('cpu')}<span>CPU u zadnjem koraku</span><strong>${s.last?.name||'Spreman za pokretanje'}</strong><small>t = ${s.t}</small></div><div class="ready-queue"><span class="label">RED SPREMNIH</span><div>${s.queue.length?s.queue.map(id=>`<span style="--process:${colors[id]}">${esc(s.jobs[id].name)}</span>`).join(''):'<small>Nema procesa u redu.</small>'}</div><p>${s.jobs.some(j=>j.state==='blocked')?'I/O čeka: '+s.jobs.filter(j=>j.state==='blocked').map(j=>j.name+' do t='+j.wake).join(', '):'Nema procesa na I/O čekanju.'}</p></div></div><h3 class="study-subtitle">Vremenska crta</h3><div class="timeline" aria-label="Raspored procesora">${segments.length?segments.map(seg=>`<div style="min-width:${Math.max(35,(seg.end-seg.start)*25)}px;flex:${seg.end-seg.start};--process:${seg.id===null?'#adb0bb':colors[seg.id]}"><strong>${esc(seg.name)}</strong><small>${seg.start}–${seg.end}</small></div>`).join(''):'<span class="empty-state">Pokreni prvi korak.</span>'}</div><div class="table-scroll"><table class="study-table"><thead><tr><th>Proces</th><th>Stanje nakon koraka</th><th>CPU iskorišten</th><th>Čekanje na CPU</th><th>Odziv</th><th>Obrtaj</th></tr></thead><tbody>${s.jobs.map(j=>`<tr><td><span class="process-dot" style="background:${colors[j.id]}"></span>${esc(j.name)}</td><td><span class="state-pill state-${j.state}">${states[j.state]}</span></td><td>${j.used} / ${j.burst}</td><td>${j.wait}</td><td>${j.first===null?'—':j.first-j.arrival}</td><td>${j.finish===null?'—':j.finish-j.arrival}</td></tr>`).join('')}</tbody></table></div><details class="study-details" open><summary>Procesi i primjeri</summary><div class="example-buttons">${[['basic','Svi dolaze u t=0'],['arrivals','Različiti dolasci'],['io','Proces s I/O čekanjem']].map(([id,label])=>`<button class="button secondary" data-cpu-example="${id}">${label}</button>`).join('')}</div><form id="cpu-jobs"><div class="table-scroll"><table class="study-table edit-table"><thead><tr><th>Naziv</th><th>Dolazak</th><th>Ukupno CPU</th><th>I/O nakon CPU</th><th>Trajanje I/O</th><th></th></tr></thead><tbody>${config.jobs.map((j,i)=>`<tr data-job="${i}"><td><input name="job-name" value="${esc(j.name)}" maxlength="12" aria-label="Naziv procesa ${i+1}"></td>${[['arrival','Dolazak'],['burst','CPU'],['ioAt','I/O nakon'],['ioFor','Trajanje I/O']].map(([key,label])=>`<td><input type="number" name="${key}" value="${j[key]}" min="0" max="30" aria-label="${label} procesa ${i+1}"></td>`).join('')}<td><button type="button" class="icon-button" data-remove-job="${i}" aria-label="Ukloni proces ${i+1}" ${config.jobs.length===1?'disabled':''}>${icon('close')}</button></td></tr>`).join('')}</tbody></table></div><div class="study-actions"><button class="button primary">Primijeni procese</button><button type="button" class="button secondary" id="add-job" ${config.jobs.length>=8?'disabled':''}>Dodaj proces</button></div></form><p class="form-hint">I/O 0/0 znači bez prekida. Primjer 2/3: nakon 2 odrađene CPU jedinice proces čeka I/O 3 jedinice. Promjena ulaza vraća model na početak.</p></details><details class="study-details"><summary>Usporedi algoritme na istim ulazima</summary><table class="study-table"><thead><tr><th>Algoritam</th><th>Prosječno čekanje</th><th>Prosječan odziv</th><th>Prosječan obrtaj</th></tr></thead><tbody>${comparison.map(row=>`<tr><td>${algorithms[row.algorithm]}</td><td>${fmt(row.waiting)}</td><td>${fmt(row.response)}</td><td>${fmt(row.turnaround)}</td></tr>`).join('')}</tbody></table><p class="study-text">Odziv = prvo izvođenje − dolazak. Obrtaj = završetak − dolazak. Čekanje broji samo vrijeme u redu spremnih, ne I/O čekanje. Niži prosjek nije jedini kriterij izbora algoritma.</p></details><div class="model-note">Model ima jedan CPU, najviše jedan I/O prekid po procesu i nulti trošak prebacivanja konteksta. Trajanja su unaprijed poznata. Na granici koraka novi dolasci i završeci I/O-a ulaze u red prije procesa kojem je istekao kvant. Ovi pokusi su odvojeni od popisa otvorenih aplikacija.</div></div>`;
    const configure=fn=>set(()=>{fn(fs.state.learning.cpu);fs.state.learning.cpu.steps=0;},['cpu']);
    $('#cpu-algorithm',c).onchange=e=>configure(v=>{v.algorithm=e.target.value;});$('#cpu-quantum',c).onchange=e=>configure(v=>{v.quantum=Number(e.target.value);});
    const advance=steps=>set(()=>{const v=fs.state.learning.cpu;const result=cpuRun(v,steps);v.steps=result.t;if(cpuSummary(result).done){fs.state.learning.evidence['cpu_'+v.algorithm]=true;if(v.jobs.some(j=>j.ioAt))fs.state.learning.evidence.cpu_io=true;}},['cpu','lab']);
    $('#cpu-step',c).onclick=()=>advance(config.steps+1);$('#cpu-run',c).onclick=()=>advance(400);$('#cpu-reset',c).onclick=()=>configure(()=>{});
    for(const b of $$('[data-cpu-example]',c))b.onclick=()=>configure(v=>{v.jobs=JSON.parse(JSON.stringify(CPU_EXAMPLES[b.dataset.cpuExample]));});
    $('#cpu-jobs',c).onsubmit=e=>{e.preventDefault();try{const jobs=$$('[data-job]',c).map(row=>({name:$('[name=job-name]',row).value,arrival:Number($('[name=arrival]',row).value),burst:Number($('[name=burst]',row).value),ioAt:Number($('[name=ioAt]',row).value),ioFor:Number($('[name=ioFor]',row).value)}));checkJobs(jobs);configure(v=>{v.jobs=jobs;});}catch(err){toast(err.message);}};
    $('#add-job',c).onclick=()=>configure(v=>{let n=1;while(v.jobs.some(j=>j.name==='P'+n))n++;v.jobs.push({name:'P'+n,arrival:0,burst:3,ioAt:0,ioFor:0});});for(const b of $$('[data-remove-job]',c))b.onclick=()=>configure(v=>{v.jobs.splice(Number(b.dataset.removeJob),1);});
  }

  function memory(c){
    const config=fs.state.learning.memory,s=pageRun(config,config.steps),last=s.history.at(-1),translation=translateAddress(s,address);
    const compare=['fifo','lru'].map(algorithm=>({algorithm,...pageRun({...config,algorithm})}));
    c.innerHTML=`<div class="study-app">${intro('VIRTUALNA MEMORIJA','Stranice traže svoje okvire.','Virtualni prostor dijeli se na stranice, fizički RAM na jednako velike okvire. Tablica stranica povezuje ta dva prostora.')}<div class="sim-controls"><label>Algoritam zamjene<select id="memory-algorithm"><option value="fifo" ${config.algorithm==='fifo'?'selected':''}>FIFO — prva učitana izlazi</option><option value="lru" ${config.algorithm==='lru'?'selected':''}>LRU — najdulje nekorištena izlazi</option></select></label><label>Okviri RAM-a<select id="memory-frames">${[2,3,4,5].map(n=>`<option ${config.frames===n?'selected':''}>${n}</option>`).join('')}</select></label><button class="button primary" id="memory-step" ${s.step===s.refs.length?'disabled':''}>${icon('play')} Sljedeći pristup</button><button class="button secondary" id="memory-run" ${s.step===s.refs.length?'disabled':''}>Do kraja</button><button class="button subtle" id="memory-reset">Početak</button></div><form class="reference-form" id="reference-form"><label>Slijed pristupa stranicama<input id="memory-sequence" value="${esc(config.sequence)}" maxlength="100"></label><button class="button secondary">Primijeni slijed</button></form><p class="form-hint">Stranice su 0–7. <code>1w</code> znači zapis u stranicu 1; broj bez w znači čitanje. Svaki okvir ima 1 KiB (1024 bajta).</p><div class="metrics three"><div class="metric"><span class="metric-label">PRISTUPI</span><div class="metric-value">${s.step}<span>/ ${s.refs.length}</span></div></div><div class="metric"><span class="metric-label">PROMAŠAJI STRANICE</span><div class="metric-value">${s.faults}<span>page faults</span></div></div><div class="metric"><span class="metric-label">POGOCI / UPISI NA DISK</span><div class="metric-value">${s.hits}<span>/ ${s.writebacks}</span></div></div></div><h3 class="study-subtitle">RAM · ${config.frames} KiB</h3><div class="frame-grid" style="--frames:${config.frames}">${s.frames.map((f,i)=>`<div class="memory-frame ${f?'occupied':''}" style="--process:${f?colors[f.page]:'#ddd'}"><small>OKVIR ${i}</small><strong>${f?'P'+f.page:'Slobodan'}</strong><span>${f?(f.dirty?'Izmijenjena · dirty':'Čista kopija'):'—'}</span></div>`).join('')}</div><div class="step-explanation" role="status">${!last?'Pokreni pristup i prati koji se okvir popunjava.':last.hit?`Pogodak: stranica P${last.page} već je u okviru ${last.frame}.${last.write?' Zapis je označava izmijenjenom.':''}`:`Promašaj: P${last.page} nije bila u RAM-u. ${last.evicted!==null?`Izbačena je P${last.evicted}${last.wroteBack?' uz upis izmijenjene kopije na disk':''}.`:'Pronađen je slobodan okvir.'} P${last.page} učitana je u okvir ${last.frame}.`}</div><div class="reference-track" aria-label="Pristupi memoriji">${s.refs.map((ref,i)=>`<span class="${i<s.step?(s.history[i].hit?'hit':'fault'):i===s.step?'next':''}" title="${i<s.step?s.history[i].hit?'Pogodak':'Promašaj':'Čeka pristup'}">${ref.page}${ref.write?'w':''}</span>`).join('')}</div><div class="memory-columns"><div><h3 class="study-subtitle">Tablica stranica</h3><table class="study-table"><thead><tr><th>Virtualna stranica</th><th>U RAM-u</th><th>Okvir</th></tr></thead><tbody>${Array.from({length:8},(_,p)=>{const i=s.frames.findIndex(f=>f?.page===p);return `<tr><td>P${p}</td><td>${i<0?'Ne':'Da'}</td><td>${i<0?'—':i}</td></tr>`;}).join('')}</tbody></table></div><div><h3 class="study-subtitle">Prevođenje adrese</h3><label class="study-field">Virtualna adresa (0–8191)<input id="virtual-address" type="number" min="0" max="8191" value="${address}"></label><div class="translation-result"><span>Stranica <strong>${translation.page}</strong></span><span>Pomak <strong>${translation.offset}</strong></span><p>${translation.physical===null?'Stranica nije prisutna. Pristup bi izazvao promašaj stranice.':`Fizička adresa: ${translation.frame} × 1024 + ${translation.offset} = <strong>${translation.physical}</strong>.`}</p></div><p class="form-hint">Ovaj izračun samo provjerava trenutačnu tablicu i ne učitava stranicu.</p></div></div><details class="study-details"><summary>Usporedi FIFO i LRU</summary><table class="study-table"><thead><tr><th>Algoritam</th><th>Pogoci</th><th>Promašaji</th><th>Upisi izmijenjenih stranica</th></tr></thead><tbody>${compare.map(row=>`<tr><td>${row.algorithm.toUpperCase()}</td><td>${row.hits}</td><td>${row.faults}</td><td>${row.writebacks}</td></tr>`).join('')}</tbody></table><p class="study-text">LRU se vodi posljednjim korištenjem, FIFO vremenom učitavanja. Zato mogu odabrati različitu stranicu za zamjenu.</p></details><div class="model-note">U ovom pokusu svih osam virtualnih stranica ima kopiju u pomoćnom spremištu. Učitavanje na zahtjev je pojednostavljeno: ne prikazujemo trajanje diskovnog I/O-a, TLB ni više procesa. U stvarnom sustavu promašaj stranice ne mora uvijek značiti čitanje s diska. Virtualna memorija nije dodatni fizički RAM.</div></div>`;
    const configure=fn=>set(()=>{fn(fs.state.learning.memory);fs.state.learning.memory.steps=0;},['memory']);
    $('#memory-algorithm',c).onchange=e=>configure(v=>{v.algorithm=e.target.value;});$('#memory-frames',c).onchange=e=>configure(v=>{v.frames=Number(e.target.value);});
    $('#reference-form',c).onsubmit=e=>{e.preventDefault();const value=$('#memory-sequence',c).value;try{parseReferences(value);configure(v=>{v.sequence=value;});}catch(err){toast(err.message);}};
    const advance=steps=>set(()=>{const v=fs.state.learning.memory;const result=pageRun(v,steps);v.steps=result.step;if(result.step===result.refs.length){fs.state.learning.evidence['memory_'+v.algorithm]=true;}},['memory','lab']);
    $('#memory-step',c).onclick=()=>advance(s.step+1);$('#memory-run',c).onclick=()=>advance(30);$('#memory-reset',c).onclick=()=>configure(()=>{});
    $('#virtual-address',c).onchange=e=>{try{const value=Number(e.target.value);translateAddress(s,value);address=value;memory(c);}catch(err){toast(err.message);}};
  }

  function drive(c){const d=fs.state.learning.disk,used=d.files.reduce((n,f)=>n+f.blocks.length,0),fragmented=d.files.filter(f=>fragments(f)>1).length;const bytes=fs.state.nodes.filter(n=>n.type==='file').reduce((sum,n)=>sum+new TextEncoder().encode(n.content).length,0);
    c.innerHTML=`<div class="study-app">${intro('POHRANA I DATOTEČNI SUSTAV','Gdje žive datoteke?','Pokusni disk ima 32 bloka po 4 KiB. Dodjela blokova ovdje je odvojena od tvojih tekstova u Datotekama.')}<div class="metrics three"><div class="metric"><span class="metric-label">ZAUZETO</span><div class="metric-value">${used*4}<span>/ 128 KiB</span></div></div><div class="metric"><span class="metric-label">SLOBODNI BLOKOVI</span><div class="metric-value">${32-used}</div></div><div class="metric"><span class="metric-label">FRAGMENTIRANE DATOTEKE</span><div class="metric-value">${fragmented}</div></div></div><div class="disk-map" aria-label="32 bloka pokusnog diska">${Array.from({length:32},(_,i)=>{const owner=d.files.findIndex(f=>f.blocks.includes(i));return `<div class="disk-block ${owner<0?'free':'used'}" style="--process:${owner<0?'#e8e3ef':colors[owner%colors.length]}" title="Blok ${i}: ${owner<0?'slobodan':esc(d.files[owner].name)}"><small>${i}</small><strong>${owner<0?'·':esc(d.files[owner].id)}</strong></div>`;}).join('')}</div><form id="allocate-form" class="sim-controls"><label>Naziv<input name="filename" maxlength="30" placeholder="Projekt" required></label><label>Blokovi<input name="blocks" type="number" min="1" max="32" value="4" required></label><label>Način dodjele<select name="method"><option value="split">Prvi slobodni blokovi</option><option value="continuous">Neprekinuti niz</option></select></label><button class="button primary">Dodaj zapis</button></form><div class="table-scroll"><table class="study-table"><thead><tr><th>Zapis</th><th>Veličina</th><th>Blokovi</th><th>Fragmenti</th><th></th></tr></thead><tbody>${d.files.map((f,i)=>`<tr><td><span class="process-dot" style="background:${colors[i%colors.length]}"></span>${esc(f.name)} · ${f.id}</td><td>${f.blocks.length*4} KiB</td><td class="mono">${f.blocks.join(', ')}</td><td>${fragments(f)}</td><td><button class="button subtle" data-free="${f.id}" aria-label="Ukloni pokusni zapis ${esc(f.name)}">Ukloni</button></td></tr>`).join('')||'<tr><td colspan="5">Pokusni disk je prazan.</td></tr>'}</tbody></table></div><div class="study-actions"><button class="button secondary" id="disk-example">Učitaj primjer fragmentacije</button><button class="button primary" id="disk-compact" ${!d.files.length?'disabled':''}>Posloži blokove</button><button class="button subtle" id="disk-clear" ${!d.files.length?'disabled':''}>Isprazni pokusni disk</button></div><div class="model-note"><strong>Fragmentacija datoteke</strong> znači da njezini blokovi čine više odvojenih nizova. Ukupno slobodan prostor ne jamči jedan dovoljno velik neprekinuti niz. „Posloži blokove” prikazuje idealizirano preslagivanje; nije preporuka za ručnu defragmentaciju SSD-a. Ovo nije implementacija NTFS-a ili FAT-a.</div><div class="actual-storage"><div><span class="label">TVOJE STVARNE ORBIT BILJEŠKE</span><h3>${fs.state.nodes.filter(n=>n.type==='file').length} tekstualnih datoteka · ${(bytes/1024).toFixed(1)} KiB sadržaja</h3><p>To su bajtovi teksta, bez metapodataka i Koša. Model blokova iznad ne mijenja ove datoteke.</p></div><button class="button secondary" data-study-open="settings">Sigurnosna kopija</button></div></div>`;
    $('#allocate-form',c).onsubmit=e=>{e.preventDefault();const f=e.currentTarget;set(()=>{allocate(fs.state.learning.disk,f.elements.filename.value,Number(f.elements.blocks.value),f.elements.method.value==='continuous');if(fs.state.learning.disk.files.some(x=>fragments(x)>1))fs.state.learning.evidence.disk_fragmented=true;},['drive','lab']);};
    for(const b of $$('[data-free]',c))b.onclick=()=>set(()=>{fs.state.learning.disk.files=fs.state.learning.disk.files.filter(f=>f.id!==b.dataset.free);},['drive']);
    const replace=async mode=>{if(d.files.length){const ok=await ask({title:'Zamijeniti pokusni raspored?',description:'Mijenja se samo model od 32 bloka u ovoj aplikaciji. Bilješke u Datotekama ostaju sačuvane.',confirm:'Primijeni primjer'});if(!ok)return;}set(()=>{fs.state.learning.disk=mode==='example'?fragmentedDisk():emptyDisk();if(mode==='example')fs.state.learning.evidence.disk_fragmented=true;},['drive','lab']);};
    $('#disk-example',c).onclick=()=>replace('example');$('#disk-clear',c).onclick=()=>replace('empty');$('#disk-compact',c).onclick=()=>set(()=>{if(fragmented)fs.state.learning.evidence.disk_compacted=true;defragment(fs.state.learning.disk);},['drive','lab']);bindOpen(c);
  }

  function trash(c){const entries=fs.state.archive.filter(e=>fs.user.admin||e.by===fs.user.id);c.innerHTML=`<div class="study-app">${intro('OPORAVAK DATOTEKA','Druga prilika za zapis.','Brisanje kroz Datoteke premješta stavku u Koš. Vraćanje čuva sadržaj, vlasništvo i dozvole.')}<div class="table-scroll"><table class="study-table"><thead><tr><th>Naziv</th><th>Obrisao</th><th>Stavki</th><th></th></tr></thead><tbody>${entries.map(e=>{const root=e.nodes.find(n=>n.id===e.rootId);return `<tr><td>${icon(root.type==='dir'?'files':'file')} ${esc(root.name)}</td><td>${esc(e.by)}</td><td>${e.nodes.length}</td><td><button class="button secondary" data-restore="${esc(e.key)}">Vrati</button></td></tr>`;}).join('')||'<tr><td colspan="4">Nema stavki za ovaj profil.</td></tr>'}</tbody></table></div><div class="model-note">Ako je izvorna mapa uklonjena, zapis se vraća u Dokumente. Za vraćanje treba dozvola pisanja i prolaza na odredištu. Koš i sigurnosna kopija imaju različite svrhe: kopiju je potrebno preuzeti iz preglednika.</div><div class="study-actions"><button class="button secondary" data-study-open="files">Otvori Datoteke</button><button class="button secondary" data-study-open="settings">Preuzmi kopiju</button></div></div>`;for(const b of $$('[data-restore]',c))b.onclick=()=>{try{fs.restore(b.dataset.restore);ctx.changed();ctx.refresh('trash','lab');toast('Stavka je vraćena.');}catch(e){toast(e.message);}};bindOpen(c);}
  function journal(c){c.innerHTML=`<div class="study-app">${intro('DOGAĐAJI U ORBITU','Što se upravo dogodilo?','Lokalni dnevnik bilježi promjene datoteka, profila i dozvola. Ne prikuplja aktivnosti izvan ove aplikacije.')}<div class="study-actions"><button class="button secondary" id="export-journal">${icon('download')} Preuzmi dnevnik</button></div><div class="event-list">${[...fs.state.events].reverse().map(e=>`<article class="event-row ${e.kind==='odbijeno'?'denied':''}"><span>${icon(e.kind==='odbijeno'?'lock':'check')}</span><div><strong>${esc(e.text)}</strong><small>${esc(e.user)} · ${esc(e.kind)} · ${esc(new Date(e.at).toLocaleString('hr-HR'))}</small></div></article>`).join('')||'<p class="empty-state">Prve radnje pojavit će se ovdje.</p>'}</div><p class="form-hint">Čuva se zadnjih 80 događaja. Dnevnik je dio nastavnog modela i može se izmijeniti zajedno s lokalnom kopijom.</p></div>`;$('#export-journal',c).onclick=()=>download('Orbit-dnevnik.txt',fs.state.events.map(e=>`${e.at}\t${e.user}\t${e.kind}\t${e.text}`).join('\n'));}

  const lessons=[
    {id:'basics',title:'Datoteka, aplikacija, proces',time:'10–15 min',app:'files',concept:'Datoteka čuva podatke. Aplikacija ih obrađuje. Proces je program koji se izvodi. Minimiziranje mijenja prikaz prozora, a zatvaranje završava proces simulirane aplikacije.',steps:['U Datotekama otvori Dokumente i izradi mapu Moja_vjezba.','U toj mapi izradi biljeska.txt. Napiši barem 20 znakova o ulozi OS-a.','Minimiziraj Bilješke. U Procesima provjeri da su još na popisu, zatim klikni Završi uz Bilješke. Ponovno otvori datoteku.'],checks:['Mapa postoji','Bilješka sadrži tekst','Bilješke minimizirane i završene'],question:'Zašto datoteka ostaje dostupna nakon što je proces Bilješke završio?',answer:'Proces je privremen izvođač programa; spremljeni sadržaj datoteke ima trajniji životni vijek. U Orbitu je spremljen u lokalne podatke preglednika.'},
    {id:'recovery',title:'Kopiranje i oporavak',time:'10 min',app:'files',concept:'Kopiranje stvara novi zapis, premještanje mijenja njegovu lokaciju. Koš omogućuje povrat obrisanog zapisa. Sigurnosna kopija služi oporavku i kad lokalni podaci više nisu dostupni.',steps:['Odaberi biljeska.txt, klikni Kopiraj, prijeđi u Dokumente i klikni Zalijepi. Ako naziv postoji, zadaj drugi.','Jednu probnu kopiju premjesti u Koš. Otvori Koš iz izbornika aplikacija i klikni Vrati.','U Postavkama pokreni preuzimanje sigurnosne kopije. Spremi preuzetu JSON datoteku na računalo.'],checks:['Datoteka kopirana','Stavka vraćena iz Koša','Pokrenuto preuzimanje kopije'],question:'Zašto Koš nije zamjena za sigurnosnu kopiju spremljenu odvojeno od ovog radnog prostora?',answer:'Koš je dio istih lokalnih podataka. Brisanje podataka web-mjesta može ukloniti i datoteke i Koš. Preuzeta kopija nalazi se izvan tog prostora; treba provjeriti da je stvarno spremljena.'},
    {id:'permissions',title:'Vlasnik, grupa i ostali',time:'15–20 min',app:'users',concept:'r je čitanje, w pisanje, a x izvođenje datoteke ili prolaz kroz mapu. Za korisnika se odabire samo jedan skup dozvola: vlasnik, grupa ili ostali. Npr. 640 znači rw- r-- ---.',steps:['U Korisnicima otvori Dozvole i klikni Pripremi primjer 640. Zapamti naziv novog zapisa.','Kao Učenik isprobaj čitanje. Prebaci na Kolegu i ponovi: pripada istoj grupi i smije čitati, ali ne pisati.','Prebaci na Gosta i isprobaj čitanje istog zapisa. Pristup treba biti odbijen. Vrati se na Učenika.'],checks:['Dozvole promijenjene','Čitanje kao član grupe','Pristup odbijen'],question:'Što bi značile dozvole 600 umjesto 640 za Kolegu i Gosta?',answer:'S 600 samo vlasnik ima r i w. Kolega gubi pravo čitanja unatoč članstvu u grupi; Gost ga ni prije nije imao. Administrator modela izuzet je iz tih ograničenja.'},
    {id:'cpu',title:'Tko sljedeći dobiva CPU?',time:'15–20 min',app:'cpu',concept:'Proces spreman za rad može čekati CPU. FCFS zadržava proces do završetka ili čekanja na I/O. Round Robin ograničava uzastopno korištenje kvantom i vraća proces u red spremnih.',steps:['U CPU laboratoriju učitaj primjer Svi dolaze u t=0. S FCFS-om prođi nekoliko koraka, zatim Do kraja.','Odaberi Round Robin, kvant 2 i pokreni isti primjer Do kraja.','Otvori Usporedi algoritme. Usporedi prosječan odziv i čekanje. Promijeni kvant na 1 pa na 6 i promatraj vremensku crtu.'],checks:['Dovršen FCFS pokus','Dovršen Round Robin pokus'],question:'Zašto manji kvant može poboljšati odziv, a u stvarnom sustavu donijeti i dodatni trošak?',answer:'Procesi ranije dođu na red, ali učestalije prebacivanje konteksta troši procesorsko vrijeme. Ovaj model taj trošak postavlja na nulu, pa ne služi za izbor optimalnog stvarnog kvanta.'},
    {id:'io',title:'Spreman nije isto što i blokiran',time:'10–15 min',app:'cpu',concept:'Proces koji čeka I/O ne može nastaviti dok se događaj ne dovrši. Zato nije u redu spremnih. CPU u međuvremenu može izvršavati drugi spreman proces.',steps:['U CPU laboratoriju učitaj Proces s I/O čekanjem. Odaberi FCFS.','Idi korak po korak dok P1 ne prijeđe u Čeka I/O. Usporedi stanje P1 i red spremnih.','Dovrši pokus. Uključi SJF i dovrši isti primjer. Primijeti da su procjene odsječaka u ovom modelu unaprijed poznate.'],checks:['Dovršen pokus s I/O-om','Dovršen SJF pokus'],question:'Može li povećanje prioriteta samo po sebi omogućiti rad procesu koji još čeka diskovni I/O?',answer:'Ne. Prvo mora biti zadovoljen uvjet na koji proces čeka. Prioritet je važan pri izboru među procesima koji su spremni za izvođenje.'},
    {id:'memory',title:'Stranice, okviri i zamjena',time:'20 min',app:'memory',concept:'Stranica pripada virtualnom prostoru, a okvir fizičkom RAM-u. Promašaj nastaje kada tražena stranica nije prisutna. Ako nema slobodnog okvira, pravilo zamjene bira stranicu koja se izbacuje.',steps:['U Memoriji ostavi tri okvira i početni slijed. S FIFO-om prođi prva četiri pristupa, zatim Do kraja.','Odaberi LRU i ponovi isti slijed. U usporedbi zabilježi broj promašaja i upisa izmijenjenih stranica.','Upiši virtualnu adresu 1024. Odredi stranicu i pomak te pogledaj postoji li trenutačno fizička adresa.'],checks:['Dovršen FIFO pokus','Dovršen LRU pokus'],question:'Zašto se izmijenjena stranica pri izbacivanju mora sačuvati, a čista se u ovom modelu može samo odbaciti?',answer:'Čista stranica ima važeću kopiju u pomoćnom spremištu. Izmijenjena sadržava novije podatke, pa se prije gubitka okvira mora zapisati. Page fault općenito ne znači uvijek fizičko čitanje s diska.'},
    {id:'disk',title:'Blokovi i fragmentacija',time:'10–15 min',app:'drive',concept:'Datotečni sustav evidentira koji blokovi pripadaju kojoj datoteci. Datoteka je fragmentirana kada se njezini blokovi nalaze u više odvojenih nizova. Slobodan prostor također može biti razdvojen.',steps:['U Disku učitaj primjer fragmentacije. Pronađi Projekt i provjeri raspored njegovih blokova.','Klikni Posloži blokove. Usporedi broj fragmenata, zauzet prostor i sadržaj popisa datoteka.','Objasni što je preslagivanje promijenilo, a što je ostalo jednako.'],checks:['Učitan ili stvoren fragmentiran raspored','Presložen fragmentiran raspored'],question:'Zašto jednaka ukupna količina slobodnog prostora ne jamči uspjeh dodjele neprekinutog niza blokova?',answer:'Slobodni blokovi mogu biti podijeljeni u manje rupe. Zbroj je dovoljan, ali nijedna rupa zasebno ne zadovoljava traženu duljinu.'},
    {id:'terminal',title:'Isti sustav, drugo sučelje',time:'15 min',app:'terminal',concept:'Grafičko sučelje i terminal mogu pokretati iste osnovne radnje. Putanja određuje zapis, a dozvole se provjeravaju bez obzira na sučelje. Orbit podržava samo naredbe navedene u help.',steps:['Kao Učenik u Terminalu upiši help, zatim whoami i ls -l /Dokumenti.','Naredbom echo "Moj zapis iz terminala" > /Dokumenti/terminal.txt izradi datoteku. Otvori je u Datotekama i promijeni tekst.','Vrati se u Terminal i pročitaj cat /Dokumenti/terminal.txt. U Dnevniku pogledaj izradu i ostale događaje.'],checks:['Datoteka izrađena preko terminala','Datoteka pročitana preko terminala'],question:'Zašto ograničenje čitanja mora vrijediti i u Terminalu i u grafičkom uređivaču?',answer:'Dozvole štite pristup podatku, a ne samo pojedini gumb. Kad bi ih jedno sučelje zanemarivalo, korisnik bi ga mogao iskoristiti za zaobilaženje pravila.'}
    ,{id:'network',title:'Adresa, naziv i usluga',time:'15–20 min',app:'network',concept:'IP adresa označava mrežno sučelje. Maska određuje lokalnu mrežu, a pristupnik vodi prema drugim mrežama. DNS vraća adresu za naziv. Ping provjerava ICMP odgovor; HTTP zahtjev provjerava web-uslugu.',steps:['U Mreži pročitaj uvod i topologiju. U prikazu Izazovi vrati ispravnu mrežu za slobodni pokus, zatim se vrati na Pokus i postavke.','Pokreni Ping susjeda, DNS upit i Otvori portal. U svakom rezultatu pročitaj korake i objasni čemu služi pojedina provjera.','U Terminalu upiši ipconfig /all, nslookup portal.skola.test i curl http://portal.skola.test. U Mreži pogledaj da su i te provjere zapisane u istoj povijesti.'],checks:['Uspješan ping susjeda','Dobiven DNS odgovor','Dobiven HTTP odgovor'],question:'Zašto uspješan DNS odgovor još ne dokazuje da se web-stranica može dohvatiti?',answer:'DNS je vratio adresu. Tek treba provjeriti mrežni put do nje, dopuštenje prometa prema potrebnom priključku i dostupnost usluge. Svaki od tih koraka može zasebno zakazati.'},
    {id:'network-repair',title:'Dijagnosticiraj prije popravka',time:'25–35 min',app:'network',concept:'Dijagnostika povezuje simptom, provjeru i mogući uzrok. Početna provjera stvara dokaz kvara; ponovljena provjera nakon promjene pokazuje učinak popravka. Mijenjaj jednu relevantnu postavku i zapiši zaključak.',steps:['U Mreži otvori Izazovi i učitaj IP radi, naziv ne radi. Prije promjene pokreni DNS upit. Provjeri postavku DNS-a, ispravi je, pa ponovi DNS upit i Otvori portal.','Vrati se u Izazove, napiši osvrt i klikni Provjeri završetak izazova. Zatim istim postupkom riješi Lokalno radi, portal ne; na kraju trebaju proći Ping susjeda i Otvori portal.','Učitaj Nema pinga, ali portal radi. Pokreni Ping poslužitelja i Otvori portal uz uključenu blokadu ICMP-a. Zapiši zašto nema potrebe ukloniti to pravilo da bi web radio.','Preostale izazove riješi za dodatnu vježbu. U Izvještaju upiši oznaku rada, pregledaj osvrte i kopiraj sadržaj za Word ili odaberi ispis/PDF.'],checks:['Dovršen DNS izazov','Dovršen izazov pristupnika','Objašnjen slučaj blokiranog ICMP-a'],question:'Koje dokaze trebaš navesti da bi nastavnik mogao razumjeti tvoj postupak i učinak promjene?',answer:'Početni simptom i neuspješnu provjeru, izdvojeni mogući uzrok, konkretnu promijenjenu postavku te rezultat ponovljene provjere. Kod blokiranog ICMP-a treba pokazati da HTTP radi i bez promjene tog pravila.'}
    ,{id:'recovery',title:'Verzija, kopija i oporavak',time:'20–25 min',app:'recovery',concept:'Automatsko spremanje bilješke čuva njezin trenutačni sadržaj. Ručno sačuvana verzija pamti stariji trenutak. Obje su u istom lokalnom prostoru preglednika. Sigurnosnu JSON kopiju treba spremiti izvan tog prostora i provjeriti može li se iz nje vratiti traženi tekst.',steps:['Kao Učenik u Datotekama izradi tekst Oporavak-vjezba.txt. Upiši barem dvije rečenice. U Bilješkama klikni Verzije, upiši oznaku Prije izmjene i klikni Sačuvaj verziju.','Vrati se u Bilješke i zamijeni jednu rečenicu. Ponovno otvori Verzije. Usporedi sačuvani i trenutačni tekst pa klikni Vrati kao novu datoteku. Otvori obnovljeni zapis i potvrdi da stari sadržaj postoji, a izmijenjeni izvornik ostaje.','U Oporavku otvori Kopija prostora i preuzmi JSON kopiju. Provjeri datoteku u preuzimanjima. Učitaj je preko Odaberi JSON datoteku. Ako preuzimanje nije dostupno, koristi Prikaži JSON za kopiranje, spremi cijeli tekst kao .json ili ga zalijepi u polje za pregled.','U pregledu odaberi jednu datoteku i klikni Vrati odabrane kao nove kopije. Otvori mapu Oporavak u Dokumentima i pročitaj vraćeni tekst. Samo prepoznavanje valjanog JSON-a nije provjera uspješnog oporavka.'],checks:['Sačuvana verzija teksta','Vraćena različita ili obrisana verzija kao novi tekst','Učitana i provjerena JSON kopija','Odabrani tekstovi vraćeni iz kopije'],question:'Što bi izgubio brisanjem podataka preglednika ako imaš samo verzije u njemu, a što možeš vratiti iz valjane JSON kopije na drugom mjestu?',answer:'Brisanje podataka preglednika može ukloniti i aktivne tekstove i njihove verzije. Iz zasebno spremljene JSON kopije može se vratiti stanje obuhvaćeno trenutkom njezina izvoza. Kasnije izmjene nisu u toj kopiji. Oporavak treba probati i provjeriti sadržaj, a ne zaključiti da je uspio samo zato što datoteka postoji.'}
  ];
  function checks(){const l=fs.state.learning.evidence,folder=fs.children('docs').find(n=>n.type==='dir'&&n.name==='Moja_vjezba'),note=folder&&fs.children(folder.id).find(n=>n.type==='file'&&n.name==='biljeska.txt');return [[!!folder,!!note&&note.content.trim().length>=20,fs.state.lesson.minimized&&fs.state.lesson.ended],[!!l.copied,!!l.restored,!!l.backupExport],[!!l.permissionChanged,!!l.permissionGroup,!!l.permissionDenied],[!!l.cpu_fcfs,!!l.cpu_rr],[!!l.cpu_io,!!l.cpu_sjf],[!!l.memory_fifo,!!l.memory_lru],[!!l.disk_fragmented,!!l.disk_compacted],[!!l.terminalWrite,!!l.terminalRead],[!!l.network_local,!!l.network_dns,!!l.network_http],[!!l.network_case_dns,!!l.network_case_gateway,!!l.network_case_icmp],[!!l.versionSaved,!!l.versionRecovered,!!l.backupReviewed,!!l.backupRecovered]];}
  function lab(c){const all=checks(),l=lessons[lessonIndex],results=all[lessonIndex],done=all.filter(row=>row.every(Boolean)).length;
    c.innerHTML=`<div class="lab-workspace"><aside class="lesson-sidebar"><span class="label">NAUČI KROZ RAD</span><h2>OS laboratorij</h2><div class="course-progress"><span style="width:${done/lessons.length*100}%"></span></div><small>${done} / ${lessons.length} vježbi provjereno</small><nav>${lessons.map((lesson,i)=>`<button data-lesson="${i}" class="${i===lessonIndex?'selected':''}"><span>${all[i].every(Boolean)?icon('check'):String(i+1).padStart(2,'0')}</span><div>${lesson.title}<small>${lesson.time}</small></div></button>`).join('')}</nav><button class="button secondary" id="report-export">${icon('download')} Izvještaj i predaja</button><button class="button subtle" data-study-open="guide">Vodič i pojmovi</button></aside><div class="lesson-page"><span class="label">VJEŽBA ${String(lessonIndex+1).padStart(2,'0')} · ${l.time.toUpperCase()}</span><h2>${l.title}</h2><div class="concept-box"><strong>Prije rada</strong><p>${l.concept}</p></div><ol class="lesson-steps">${l.steps.map(s=>`<li>${s}</li>`).join('')}</ol><button class="button primary" data-study-open="${l.app}">Otvori ${ctx.appTitle(l.app)} ${icon('arrow')}</button><h3 class="study-subtitle">Provjera radnji</h3><div class="check-list">${l.checks.map((label,i)=>`<div class="${results[i]?'done':''}">${icon(results[i]?'check':'circle')}<span>${label}</span></div>`).join('')}</div><form id="reflection-form"><label><strong>Objasni svojim riječima</strong><span>${l.question}</span><textarea id="reflection" rows="3" maxlength="3000" placeholder="Zapiši što si zaključio…"></textarea></label><button class="button secondary">Spremi osvrt</button><span class="reflection-state">${fs.state.learning.answers[l.id]?'Osvrt je spremljen.':''}</span></form><details class="study-details teacher-details"><summary>Smjernice za nastavnika</summary><p>${l.answer}</p></details><div class="model-note">Oznake provjeravaju izvedene radnje lokalno. Ne ocjenjuju točnost osvrta i nisu zaštićene od izmjene. Prije predaje izvještaja nastavnik treba pregledati rad i objašnjenje učenika.</div></div></div>`;
    $('#reflection',c).value=fs.state.learning.answers[l.id]||'';
    for(const b of $$('[data-lesson]',c))b.onclick=()=>{if(saveReflectionDraft(c,l.id)){lessonIndex=+b.dataset.lesson;lab(c);}};
    $('#reflection',c).oninput=()=>{const text=$('#reflection',c).value;try{fs.transact(()=>{fs.state.learning.answers[l.id]=text;});$('.reflection-state',c).textContent='Osvrt je spremljen.';}catch(e){$('.reflection-state',c).textContent='Nije spremljeno.';toast(e.message);}};
    $('#reflection-form',c).onsubmit=e=>{e.preventDefault();if(saveReflectionDraft(c,l.id))toast('Osvrt je spremljen.');};
    $('#report-export',c).onclick=()=>openApp('report');bindOpen(c);
  }
  function saveReflectionDraft(c,id){const field=$('#reflection',c);if(!field)return true;try{fs.transact(()=>{fs.state.learning.answers[id]=field.value;});return true;}catch(e){toast(e.message);return false;}}
  function exportReport(){const all=checks();const text=['ORBIT OS — IZVJEŠTAJ O RADU','Oznaka rada: '+(fs.state.learning.label||'(nije upisana)'),new Date().toLocaleString('hr-HR'),'Samoprovjera radnji; nije automatska ocjena znanja.','',...lessons.flatMap((l,i)=>[`${i+1}. ${l.title}`, ...l.checks.map((s,j)=>`${all[i][j]?'[DA]':'[NE]'} ${s}`),'Pitanje: '+l.question,'Osvrt: '+(fs.state.learning.answers[l.id]||'(nije upisan)'),'']),courseReportText(fs.state.learning.course),explorerReportText(fs.state.learning.explorer),'','TRENUTAČNI CPU POKUS',JSON.stringify(fs.state.learning.cpu,null,2),'TRENUTAČNI POKUS MEMORIJE',JSON.stringify(fs.state.learning.memory,null,2),'',networkLogText(fs.state.learning.network),...fs.state.learning.network.records.map(r=>'Spremljeni osvrt ('+r.id+'): '+r.notes)].join('\n');download('Orbit-izvjestaj-o-radu.txt',text);}
  function report(c){
    const body=()=>buildWorkReport({lessons,checks:checks(),learning:fs.state.learning});
    c.innerHTML=`<div class="report-app"><div class="report-tools"><div><span class="label">PREGLED I PREDAJA</span><h2>Tvoj rad na jednom mjestu.</h2><p>Pregledaj potvrđene radnje i osvrte. Kopiraj ih u Word, ispiši ili spremi kao PDF preko dijaloga preglednika. Izvještaj se nikome ne šalje automatski.</p></div><label>Oznaka rada (neobvezno)<input id="report-label" maxlength="80" placeholder="npr. 3.f — rad 07" value="${esc(fs.state.learning.label)}"></label><div class="study-actions"><button class="button primary" id="report-copy">${icon('copy')} Kopiraj za Word</button><button class="button secondary" id="report-print">Ispis / PDF</button><button class="button secondary" id="report-html">${icon('download')} Preuzmi HTML za ispis</button><button class="button secondary" id="report-txt">Preuzmi TXT</button><button class="button subtle" id="report-refresh">Osvježi pregled</button></div><span id="report-label-status" role="status"></span><div id="report-output-status" class="report-output-status" role="status"></div></div><div id="report-copy-fallback" class="report-copy-fallback" hidden><p>Tekst je pripremljen za ručno kopiranje. Označi ga i kopiraj u Word; zatim po potrebi uredi tablice.</p><textarea readonly aria-label="Tekst izvještaja za kopiranje"></textarea></div><style>${REPORT_CSS}</style><div id="report-preview">${body()}</div></div>`;
    $('#report-label',c).oninput=e=>{try{fs.transact(()=>{fs.state.learning.label=e.target.value;});$('.report-meta strong',c).textContent=fs.state.learning.label||'Nije upisana';$('#report-label-status',c).textContent='Oznaka je spremljena.';}catch(err){$('#report-label-status',c).textContent='Nije spremljeno: '+err.message;}};
    $('#report-html',c).onclick=()=>download('Orbit-izvjestaj-o-radu.html',reportDocument(body()),'text/html;charset=utf-8');
    $('#report-copy',c).onclick=async()=>{
      const html=body();$('#report-preview',c).innerHTML=html;
      const text=$('#report-preview',c).innerText,status=$('#report-output-status',c);
      try{
        if(navigator.clipboard?.write&&typeof ClipboardItem!=='undefined')await navigator.clipboard.write([new ClipboardItem({'text/html':new Blob([reportDocument(html)],{type:'text/html'}),'text/plain':new Blob([text],{type:'text/plain'})})]);
        else if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(text);
        else throw new Error('Ručno kopiranje');
        status.textContent='Izvještaj je kopiran. U Wordu odaberi Zalijepi; izgled može ovisiti o postavkama lijepljenja.';
      }catch{
        const fallback=$('#report-copy-fallback',c);fallback.hidden=false;const field=$('textarea',fallback);field.value=text;field.focus();field.select();status.textContent='Automatsko kopiranje nije dostupno. Tekst je označen za Kopiraj ili Ctrl+C.';
      }
    };
    $('#report-print',c).onclick=()=>{
      document.querySelector('#print-report')?.remove();const paper=document.createElement('div');paper.id='print-report';paper.innerHTML='<style>'+REPORT_CSS+'</style>'+body();document.body.append(paper);document.body.classList.add('printing-report');
      const cleanup=()=>{document.body.classList.remove('printing-report');paper.remove();window.removeEventListener('afterprint',cleanup);};
      window.addEventListener('afterprint',cleanup);try{window.print();}catch{cleanup();$('#report-output-status',c).textContent='Ispis nije dostupan. Upotrijebi kopiranje ili preuzmi HTML.';}
    };
    $('#report-txt',c).onclick=exportReport;$('#report-refresh',c).onclick=()=>report(c);
  }
  const glossary=[['Verzija i automatsko spremanje','Automatsko spremanje ažurira trenutačni tekst. Verzija čuva odabrani raniji sadržaj. U Orbitu verzije spremaš ručno; one ostaju u istom lokalnom prostoru preglednika i same ne štite od gubitka tog prostora.'],['Provjera oporavka','Nakon vraćanja otvori zapis i provjeri traženi sadržaj. Učitavanje valjanog formata kopije ne dokazuje da je u njoj željena inačica svih podataka.'],['IP adresa i maska','IPv4 adresa označava mrežno sučelje. Maska razdvaja mrežni dio i dio domaćina. Primjer /24 znači masku 255.255.255.0; adrese 192.168.10.20 i 192.168.10.30 tada su u istoj podmreži.'],['Zadani pristupnik','Usmjerivač kojem računalo šalje pakete za ciljeve izvan izravno dostupnih mreža ako ne postoji određenija ruta. Model ima samo lokalnu i zadanu rutu.'],['DNS i DHCP','DNS pronalazi adresu povezanu s nazivom. DHCP automatski dodjeljuje mrežne postavke. To su različite usluge.'],['ICMP, HTTP i vatrozid','Ping upotrebljava ICMP Echo. HTTP je aplikacijski protokol; u pokusu se koristi TCP 80. Vatrozid može zasebno dopuštati ili blokirati promet. Uspjeh jedne provjere ne potvrđuje sve usluge.'],['Operacijski sustav','Upravlja računalnim resursima i pruža usluge programima. Orbit prikazuje odabrane mehanizme kao pojednostavljene pokuse.'],['Program i proces','Program je skup uputa; proces je instanca programa tijekom izvođenja, sa svojim stanjem i resursima.'],['Dretva','Tok izvođenja unutar procesa. Dretve istog procesa obično dijele njegov adresni prostor i druge resurse. U Istraži OS usporedi dvije dretve koje povećavaju isti podatak bez lokota i s lokotom.'],['Raspoređivač','Dio OS-a koji odlučuje koji će spremni proces ili dretva dobiti procesor.'],['Promjena konteksta','Spremanje stanja jednog izvođenja i obnova drugog. U CPU pokusu njezino je trajanje zanemareno.'],['RAM i trajna pohrana','RAM čuva aktivne podatke dok je sustav uključen. Disk/SSD služi trajnijoj pohrani. Spremljena datoteka nije isto što i aktivan proces.'],['Stranica i okvir','Stranica je dio virtualnog adresnog prostora, okvir je dio fizičke memorije jednake veličine. Tablica stranica opisuje njihovo preslikavanje.'],['Promašaj stranice','Događaj pri pristupu stranici koja nije prisutna u RAM-u ili zahtijeva posebnu obradu. Model obrađuje samo nedostajuće, valjane stranice.'],['Dozvole','Pravila čitanja, pisanja i izvođenja/prolaza. Ovdje koristimo osnovni UNIX-ov model vlasnik–grupa–ostali, bez ACL-ova i posebnih bitova.'],['NTFS i FAT','Primjeri datotečnih sustava s različitim strukturama i mogućnostima. Model 32 bloka nije preslika njihova unutarnjeg ustroja.'],['Sigurnosna kopija','Odvojena kopija podataka namijenjena oporavku. Koš, sinkronizacija i RAID sami po sebi nisu zamjena za zasebnu sigurnosnu kopiju.'],['Model i mjerenje','Brojke u CPU, memorijskim i diskovnim pokusima izračunava simulator. One ne opisuju opterećenje ili kapacitet stvarnog računala.']];
  function guide(c){c.innerHTML=`<div class="study-app">${intro('VODIČ ZA RAD','Prvo upoznaj pravila.','Kreni od Istraži OS: struktura → funkcije → mehanizmi. Zatim prijeđi na pokuse i praktične vježbe.')}<div class="guide-start"><h3>Preporučeni redoslijed</h3><button class="button primary" data-study-open="explorer">Istraži OS</button><p>Struktura i funkcije → procesi → sistemski pozivi → prekidi i kontekst → memorija → dretve i sinkronizacija. Zatim praktično: datoteke i procesi → kopiranje i oporavak → korisnici i dozvole → CPU → I/O čekanje → memorija → disk → terminal → mreža → mrežna dijagnostika → verzije i oporavak.</p><button class="button primary" data-study-open="lab">Otvori laboratorij ${icon('arrow')}</button></div><div class="guide-grid"><article><h3>Na računalu</h3><p>Prozore pomiči naslovnom trakom. Povećaj ih kvadratićem, smanji znakom −. Aplikacija ostaje otvorena dok je ne zatvoriš.</p><code>Ctrl + K</code> Pretraživanje prostora<br><code>Ctrl + Alt + T</code> Terminal<br><code>Ctrl + Alt + F</code> Datoteke<br><code>Ctrl + S</code> Spremanje bilješke</article><article><h3>Na mobitelu</h3><p>Prozor zauzima raspoloživi prostor. Odaberi zapis pa dodirni Otvori. Izbornik s kvadratićima sadrži sve aplikacije.</p></article></div><h3 class="study-subtitle">Pojmovi</h3><label class="guide-search">${icon('search')}<input id="glossary-search" placeholder="Traži pojam…" aria-label="Traži pojam"></label><div id="glossary"></div><details class="study-details"><summary>Organizacija sata za nastavnika</summary><p>Za početak demonstriraj jednu radnju, traži predviđanje učenika, zatim pokreni model i usporedi rezultat s predviđanjem. Samostalni rad prati kratkim osvrtom iz vježbe. Prikazanu provjeru radnji koristi za povratnu informaciju, a ne kao dokaz samostalnosti ili automatsku ocjenu.</p><p>Za svaki rad učenik u Moj rad upisuje oznaku i izvozi JSON kopiju. Na početku sljedećeg sata učitava tu kopiju. Na zajedničkom računalu prije promjene učenika izvezi rad pa odaberi Započni novi rad. Stvarno odvajanje podataka uređuje se korisničkim računima računala ili profilima preglednika. Izvještaji i JSON kopije predaju se ručno.</p></details><div class="model-note"><strong>Granice ovog izdanja:</strong> profili vježbe, dozvole i OS pokusi nastavni su modeli u pregledniku. Lokalno izdanje nema prijavu, stvarne korisničke račune ni središnji nastavnički pregled. Ne otvaraj isti rad u više kartica. Brisanje podataka preglednika, privatni način ili premještanje HTML datoteke može ukloniti pristup automatski spremljenom radu; koristi JSON kopije. Nema stvarnog pokretanja programa, instalacije OS-a ni slanja mrežnog prometa iz pokusa. Za učenje rada na pravom OS-u nastavi s virtualnim strojem ili školskim računalom.</div><p class="model-note">Vanjske poveznice na izvore zahtijevaju internet. Svi ugrađeni pokusi i objašnjenja dostupni su bez njega.</p>${sourceLinks}</div>`;const draw=query=>{$('#glossary',c).innerHTML=glossary.filter(([name,desc])=>(name+' '+desc).toLocaleLowerCase('hr').includes(query.toLocaleLowerCase('hr'))).map(([name,desc])=>`<details class="glossary-entry"><summary>${name}</summary><p>${desc}</p></details>`).join('')||'<p class="empty-state">Nema pojmova za taj upit.</p>';};draw('');$('#glossary-search',c).oninput=e=>draw(e.target.value);bindOpen(c);}
  return {users,cpu,memory,drive,trash,journal,lab,guide,permissions,exportReport,report};
}
